<?php
require_once '../../config/database.php';require_once '../../config/helpers.php';require_role('admin');$studentId=(int)($_GET['student_id']??$_POST['student_id']??0);$stmt=mysqli_prepare($conn,"SELECT id,student_no,full_name FROM users WHERE id=? AND role='student'");mysqli_stmt_bind_param($stmt,'i',$studentId);mysqli_stmt_execute($stmt);$student=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));$error='';
if(!$student){$students=mysqli_query($conn,"SELECT id,student_no,full_name FROM users WHERE role='student' ORDER BY full_name");}
if($student&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$subjectId=(int)($_POST['subject_id']??0);$action=$_POST['action']??'add';if($action==='add'){$stmt=mysqli_prepare($conn,'INSERT INTO enrollments(student_id,subject_id) SELECT ?,id FROM subjects WHERE id=?');mysqli_stmt_bind_param($stmt,'ii',$studentId,$subjectId);if(mysqli_stmt_execute($stmt)&&mysqli_stmt_affected_rows($stmt)>0)flash('Subject enrollment added.');else flash('Enrollment could not be added. It may already exist.','danger');}elseif($action==='remove'){$stmt=mysqli_prepare($conn,'DELETE FROM enrollments WHERE student_id=? AND subject_id=?');mysqli_stmt_bind_param($stmt,'ii',$studentId,$subjectId);mysqli_stmt_execute($stmt);flash('Enrollment removed.');}header('Location: manage.php?student_id='.$studentId);exit;}
$subjects=$student?mysqli_query($conn,'SELECT s.id,s.subject_code,s.subject_name,s.units FROM subjects s WHERE NOT EXISTS(SELECT 1 FROM enrollments e WHERE e.student_id='.(int)$studentId.' AND e.subject_id=s.id) ORDER BY s.subject_code'):false;
$enrolled=$student?mysqli_query($conn,'SELECT s.id,s.subject_code,s.subject_name,s.units FROM subjects s JOIN enrollments e ON e.subject_id=s.id WHERE e.student_id='.(int)$studentId.' ORDER BY s.subject_code'):false;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Enrollments · Clark College Science of Technology</title><link href="../../assets/vendor/bootstrap/css/bootstrap.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><nav class="navbar"><div class="container app-container"><a class="navbar-brand" href="../dashboard.php"><img class="school-logo school-logo-nav" src="../../assets/images/school-logo.jpg" alt="Clark College of Science and Technology logo">Clark College Science of Technology</a><a class="btn btn-light btn-sm" href="../../logout.php">Sign out</a></div></nav><main class="container app-container pb-5"><div class="page-head"><div><p class="eyebrow">ACADEMIC RECORDS</p><h2>Subject enrollments</h2><p class="subheading">Assign subjects to student accounts.</p></div></div><?php show_flash();?>
<?php if(!$student):?><section class="card"><div class="card-header"><h3 class="mb-0">Choose a student</h3></div><div class="card-body"><form method="get" class="row g-3 align-items-end"><div class="col-md-9"><label class="form-label">Student</label><select class="form-select" name="student_id" required><option value="">Select a student…</option><?php while($s=mysqli_fetch_assoc($students)):?><option value="<?=(int)$s['id']?>"><?=e(($s['student_no']?:'No student number').' — '.$s['full_name'])?></option><?php endwhile;?></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Manage enrollments</button></div></form></div></section>
<?php else:?><div class="card mb-4"><div class="card-body d-flex flex-wrap align-items-center justify-content-between gap-3"><div><span class="eyebrow">SELECTED STUDENT</span><h3 class="mb-1"><?=e($student['full_name'])?></h3><span class="text-muted"><?=e($student['student_no'])?></span></div><a class="btn btn-light" href="../students/index.php">Back to students</a></div></div><div class="row g-4"><div class="col-lg-5"><section class="card h-100"><div class="card-header"><h3 class="mb-0">Add a subject</h3></div><div class="card-body"><?php if($subjects&&mysqli_num_rows($subjects)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="student_id" value="<?=$studentId?>"><input type="hidden" name="action" value="add"><label class="form-label">Available subject</label><select class="form-select mb-3" name="subject_id" required><?php while($s=mysqli_fetch_assoc($subjects)):?><option value="<?=(int)$s['id']?>"><?=e($s['subject_code'].' — '.$s['subject_name'].' ('.$s['units'].' units)')?></option><?php endwhile;?></select><button class="btn btn-primary w-100">Add enrollment</button></form><?php else:?><div class="empty-state"><strong>No available subjects</strong>All subjects may already be assigned, or the catalog is empty.</div><?php endif;?></div></section></div><div class="col-lg-7"><section class="card"><div class="card-header"><h3 class="mb-0">Enrolled subjects</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Subject</th><th>Units</th><th></th></tr></thead><tbody><?php $units=0;if($enrolled&&mysqli_num_rows($enrolled)):while($s=mysqli_fetch_assoc($enrolled)):$units+=(int)$s['units'];?><tr><td><strong><?=e($s['subject_code'])?></strong><div class="small text-muted"><?=e($s['subject_name'])?></div></td><td><?=(int)$s['units']?></td><td class="text-end"><form method="post" onsubmit="return confirm('Remove this subject enrollment?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="student_id" value="<?=$studentId?>"><input type="hidden" name="subject_id" value="<?=(int)$s['id']?>"><input type="hidden" name="action" value="remove"><button class="btn btn-outline-danger btn-sm">Remove</button></form></td></tr><?php endwhile;else:?><tr><td colspan="3"><div class="empty-state"><strong>No enrollments yet</strong>Add a subject using the form.</div></td></tr><?php endif;?></tbody></table></div><div class="card-body border-top d-flex justify-content-between"><span class="text-muted">Total enrolled units</span><strong><?=$units?> units</strong></div></section></div></div><?php endif;?></main><script src="../../assets/vendor/bootstrap/js/bootstrap.bundle.min.js"></script></body></html>
